"use client";

import { useEffect, useState, useCallback } from "react";
import { ErrorState } from "@/components/ui/error-state";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { ChevronLeft, ChevronRight, CheckCircle2, Clock, XCircle, Loader2, AlertTriangle, Calendar } from "lucide-react";
import { fmtDubai } from "@/lib/utils";
import { DashboardScrollContainer } from "@/components/DashboardScrollContainer";
import { useLanguage } from "@/lib/i18n/LanguageContext";

/* ─── Constants ─── */
const PAGE_SIZE = 20;

const STATUS_VALUES = ["all", "pending", "in_progress", "done", "cancelled"];

const STATUS_STYLES: Record<string, { bg: string; text: string; icon: React.ReactNode }> = {
  pending: { bg: "bg-amber-500/10", text: "text-amber-400", icon: <Clock className="size-3" /> },
  in_progress: { bg: "bg-blue-500/10", text: "text-blue-400", icon: <Loader2 className="size-3 animate-spin" /> },
  done: { bg: "bg-emerald-500/10", text: "text-emerald-400", icon: <CheckCircle2 className="size-3" /> },
  cancelled: { bg: "bg-gray-500/10", text: "text-muted-foreground", icon: <XCircle className="size-3" /> },
};

const PRIORITY_STYLES: Record<string, string> = {
  low: "bg-slate-500/10 text-slate-400",
  medium: "bg-blue-500/10 text-blue-400",
  high: "bg-orange-500/10 text-orange-400",
  urgent: "bg-rose-500/10 text-rose-400",
};

/* ─── Types ─── */
interface Task {
  id: string;
  title: string;
  status: string;
  priority: string;
  assigned_to: string | null;
  due_at: string | null;
  created_at: string;
  updated_at: string;
}

interface ProfileInfo {
  id: string;
  full_name: string | null;
}

/* ─── Helpers ─── */
function formatDate(d: string | null, locale: string): string {
  if (!d) return "—";
  return fmtDubai(new Date(d), { locale, month: "short", day: "numeric", year: "numeric" });
}

function isOverdue(dueAt: string | null, status: string): boolean {
  if (!dueAt || status === "done" || status === "cancelled") return false;
  return new Date(dueAt) < new Date();
}

/* ─── Component ─── */
export default function TasksPage() {
  const { lang, t } = useLanguage();

  const [tasks, setTasks] = useState<Task[]>([]);
  const [profiles, setProfiles] = useState<ProfileInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0);

  // Filters
  const [statusFilter, setStatusFilter] = useState("all");
  const [assigneeFilter, setAssigneeFilter] = useState("all");

  const statusLabels: Record<string, string> = {
    all: t("tasks.allStatuses"),
    pending: t("tasks.statusPending"),
    in_progress: t("tasks.statusInProgress"),
    done: t("tasks.statusDone"),
    cancelled: t("tasks.statusCancelled"),
  };
  const priorityLabels: Record<string, string> = {
    low: t("tasks.priorityLow"),
    medium: t("tasks.priorityMedium"),
    high: t("tasks.priorityHigh"),
    urgent: t("tasks.priorityUrgent"),
  };

  // Profile name lookup
  const profileNameMap: Record<string, string> = {};
  profiles.forEach((p) => {
    if (p.id && p.full_name) profileNameMap[p.id] = p.full_name;
  });

  /* ─── Fetch tasks from BFF API ─── */
  const fetchTasks = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams();
      params.set("page", String(page));
      if (statusFilter !== "all") params.set("status", statusFilter);
      if (assigneeFilter !== "all") params.set("assignee", assigneeFilter);

      const res = await fetch(`/api/tasks/list?${params.toString()}`);
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || t("tasks.loadFailed"));
      }
      const json = await res.json();
      setTasks((json.tasks ?? []) as Task[]);
      setProfiles((json.profiles ?? []) as ProfileInfo[]);
      setTotalCount(json.totalCount ?? 0);
    } catch (err: any) {
      console.error(t("tasks.loadFailed"), err);
      setError(err.message || t("tasks.loadFailed"));
    }
    setLoading(false);
  }, [page, statusFilter, assigneeFilter, t]);

  useEffect(() => {
    fetchTasks();
  }, [fetchTasks]);

  // Reset page when filters change
  useEffect(() => {
    setPage(0);
  }, [statusFilter, assigneeFilter]);

  const totalPages = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));

  return (
    // T3-1: tasks 根容器 = <DashboardScrollContainer className="space-y-4 p-4">
    // → 走外层 viewport 滚动模式（与 payments / quotations 一致）。
    // sticky 元素 (page-title z-20) 直接锚定到 viewport 顶部。
    // tasks 没有批量选择功能 → 无 bulk-bar；filter 状态/Assignee 行不 sticky。
    // z-index 约定: page-title z-20 / dialog z-40 (z-modal) / toast z-50 (z-toast)
    <DashboardScrollContainer className="space-y-4 p-4">
      {/* ─── Header (page-title sticky) ───
          T2-4: 锚定功能卡片 — 整页滚动时标题永远可见。
          z-index 约定: page-title z-20 / dialog z-40 (z-modal) / toast z-50 (z-toast) */}
      <div
        data-sticky-region="page-title"
        className="sticky top-0 z-20 bg-background/95 backdrop-blur-sm border-b -mx-4 px-4 py-2"
      >
        <div className="flex items-center justify-between">
          <h1 className="text-xl font-semibold">{t("tasks.title")}</h1>
          <span className="text-sm text-muted-foreground">
            {totalCount} {t("tasks.total")}
          </span>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-3">
        {/* Status filter */}
        <Select value={statusFilter} onValueChange={(v) => setStatusFilter(v ?? '')}>
          <SelectTrigger>
            <SelectValue placeholder={t("tasks.allStatuses")} />
          </SelectTrigger>
          <SelectContent>
            {STATUS_VALUES.map((status) => (
              <SelectItem key={status} value={status}>
                {statusLabels[status]}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {/* Assignee filter */}
        <Select value={assigneeFilter} onValueChange={(v) => setAssigneeFilter(v ?? '')}>
          <SelectTrigger>
            <SelectValue placeholder={t("tasks.allAssignees")} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">{t("tasks.allAssignees")}</SelectItem>
            {profiles.map((p) => (
              <SelectItem key={p.id} value={p.id}>
                {p.full_name || p.id}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Error State */}
      {error && <ErrorState message={error} onRetry={fetchTasks} />}

      {/* Loading */}
      {loading && (
        <div className="flex items-center justify-center h-48">
          <Loader2 className="size-6 animate-spin text-muted-foreground" />
        </div>
      )}

      {/* Table */}
      {!loading && !error && (
        <Card>
          <CardContent className="p-0">
            {tasks.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-48 text-muted-foreground">
                <AlertTriangle className="size-6 mb-2" />
                <p className="text-sm">{t("tasks.noTasks")}</p>
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t("tasks.columnTitle")}</TableHead>
                    <TableHead>{t("tasks.assignedTo")}</TableHead>
                    <TableHead>{t("tasks.due")}</TableHead>
                    <TableHead>{t("tasks.status")}</TableHead>
                    <TableHead>{t("tasks.priority")}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {tasks.map((task) => {
                    const s = STATUS_STYLES[task.status] || STATUS_STYLES.pending;
                    const overdue = isOverdue(task.due_at, task.status);
                    return (
                      <TableRow
                        key={task.id}
                        className="cursor-pointer"
                        onClick={() => {
                          window.location.href = `/tasks/${task.id}`;
                        }}
                      >
                        <TableCell className="font-medium max-w-[280px] truncate">
                          {task.title}
                        </TableCell>
                        <TableCell>
                          {task.assigned_to
                            ? profileNameMap[task.assigned_to] || task.assigned_to.slice(0, 8)
                            : "—"}
                        </TableCell>
                        <TableCell>
                          <span className={overdue ? "text-rose-400 font-medium" : ""}>
                            {overdue && <AlertTriangle className="size-3 inline mr-1" />}
                            {formatDate(task.due_at, lang === "zh" ? "zh-CN" : "en-US")}
                          </span>
                        </TableCell>
                        <TableCell>
                          <span
                            className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${s.bg} ${s.text}`}
                          >
                            {s.icon}
                            {statusLabels[task.status] || task.status.replace("_", " ")}
                          </span>
                        </TableCell>
                        <TableCell>
                          <span
                            className={`inline-block rounded-full px-2 py-0.5 text-xs font-medium ${PRIORITY_STYLES[task.priority] || PRIORITY_STYLES.medium}`}
                          >
                            {priorityLabels[task.priority] || task.priority}
                          </span>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            )}
          </CardContent>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between border-t px-4 py-3">
              <span className="text-sm text-muted-foreground">
                {t("tasks.page")} {page + 1} {t("tasks.of")} {totalPages}
              </span>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  disabled={page === 0}
                  onClick={() => setPage((p) => p - 1)}
                >
                  <ChevronLeft className="size-4" />
                  {t("tasks.previous")}
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  disabled={page >= totalPages - 1}
                  onClick={() => setPage((p) => p + 1)}
                >
                  {t("tasks.next")}
                  <ChevronRight className="size-4" />
                </Button>
              </div>
            </div>
          )}
        </Card>
      )}

      {/* T2-4: z-modal z-40 / z-toast z-50 层级约定 — 此页无 Dialog / Toaster
          后续若添加：<Dialog ... /> 用 z-40；<Toaster position="top-center" richColors /> 用 z-50。
          page-title 在此文件顶部已锚 z-20。 */}
    </DashboardScrollContainer>
  );
}
